require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';require_once __DIR__.'/../hr_letters.php';oecrm_require_admin_login();oecrm_require_permission($conn,'hr_letters','view');$id=(int)($_GET['id']??0);$companyId=oecrm_current_company_id($conn);$s=mysqli_prepare($conn,'SELECT l.*,e.name employee_name,e.employeeCode,e.designation,c.legal_name,c.display_name,c.address company_address,c.email company_email,c.phone company_phone,c.logo_path FROM hr_letters l JOIN employeestbl e ON e.id=l.employee_id JOIN companies c ON c.id=l.company_id WHERE l.id=? AND l.company_id=?');mysqli_stmt_bind_param($s,'ii',$id,$companyId);mysqli_stmt_execute($s);$l=mysqli_fetch_assoc(mysqli_stmt_get_result($s));mysqli_stmt_close($s);if(!$l){http_response_code(404);exit('Letter not found.');}oecrm_audit($conn,'hr_letters','view','hr_letter',$id,'HR letter viewed');
?><!doctype html><html><head><meta charset="utf-8"><title><?php echo oecrm_h($l['reference_no'].' - '.$l['employee_name']);?></title><?php echo oecrm_letter_print_styles();?></head><body><div class="toolbar"><a href="hrLetters.php">Back</a><button onclick="window.print()">Print / Save PDF</button></div><article class="letter"><header class="letter-head"><div><h1><?php echo oecrm_h($l['legal_name']?:$l['display_name']);?></h1><div><?php echo nl2br(oecrm_h($l['company_address']));?></div></div><div class="letter-meta"><strong><?php echo oecrm_h($l['reference_no']);?></strong><br><?php echo date('d M Y',strtotime($l['issue_date']));?><br><?php echo oecrm_h(ucwords(str_replace('_',' ',$l['letter_type'])));?></div></header><section class="letter-body"><h2><?php echo oecrm_h($l['subject']);?></h2><?php echo $l['body_html'];?></section><footer class="letter-footer"><?php echo oecrm_h($l['company_email']);?><?php echo $l['company_phone']?' | '.oecrm_h($l['company_phone']):'';?><br>This is a system-generated HR document. Reference: <?php echo oecrm_h($l['reference_no']);?></footer></article></body></html>
